// ── extractTriggers: pure-logic fixtures ─────────────────────────────────────

suite('workflowLint.extractTriggers', function () {

    test('block form with two triggers, nested types do not leak in', function () {
        var yml = [
            'name: AI Teammate',
            'on:',
            '  issues:',
            '    types: [assigned, labeled]',
            '  workflow_dispatch:',
            '    inputs:',
            '      issue:',
            '        type: string',
            'permissions:',
            '  contents: write'
        ].join('\n');
