function labeledEvent(labelName, opts) {
    opts = opts || {};
    return {
        eventName: 'issues',
        action: 'labeled',
        labelName: labelName,
        issue: ISSUE,
        issueLabelNames: opts.issueLabelNames || [],
        runs: opts.runs || [],
