            { applicable: true, leg: '' });
        assert.deepEqual(dedup.deriveEventLeg('assigned', null, null), { applicable: true, leg: '' });
    });
});

// ── key + window predicates ───────────────────────────────────────────────

suite('teammateEventDedup — key/window predicates', function () {

