function issueOfRunName(name) {
    if (!name || typeof name !== 'string') return null;
    var m = /#(\d+)(?!\d)/.exec(name);
    if (m) return parseInt(m[1], 10);
    var g = /(?:^|[^0-9a-zA-Z])gh-(\d+)(?!\d)/.exec(name);
    return g ? parseInt(g[1], 10) : null;
}

/**
 * The leg a run title carries, '' when unknown:
 *  - '▶ <leg> (SM) · ...'           — SM dispatch (factory title)
 *  - '🔧 rework · ...' / '🔍 review · ...' / '⚒️ dev · ...'
 *                                   — template event titles
 *  - 'teammate: ... #<n> <leg>'     — stub dispatch title (trailing leg,
 *                                     stub prefix required so an issue
 *                                     title ending in a leg word never
 *                                     aliases)
 * Event-path stub titles ('teammate: assigned #1040') carry no leg → ''.
 */
function legOfRunName(name) {
    if (!name || typeof name !== 'string') return '';
    var m = /▶\s+(dev|review|rework)\s+\(SM\)/.exec(name);
    if (m) return m[1];
    m = /(?:🔧\s*rework|🔍\s*review|⚒️?\s*dev)/.exec(name);
    if (m) {
        if (m[0].indexOf('rework') !== -1) return 'rework';
        if (m[0].indexOf('review') !== -1) return 'review';
        return 'dev';
    }
    if (name.indexOf('teammate:') === 0) {
        m = /\s(dev|review|rework)$/.exec(name);
        if (m) return m[1];
    }
    return '';
}

/**
 * gh-1028 key semantics. An event with NO declared leg (bare assign) is
 * conservative: ANY in-flight/fresh run for the issue suppresses it (the
 * assign gate is "the loop starts" — one run per issue is the promise).
 * A run with no leg in its title only suppresses events that also declare
 * no leg — a KNOWN different leg must proceed (the concurrency group
 * serializes it behind the in-flight run; swallowing it would kill a
 * genuinely new leg request).
 */
